function structuredData({ route, title, description, canonical, ogImage }) {
  const organizationId = `${siteUrl}/#organization`;
  const websiteId = `${siteUrl}/#website`;
  const pageId = `${canonical}#webpage`;
  const cleanTitle = decodeMetadata(title);
  const cleanDescription = decodeMetadata(description);
  const routeDefinition = routesMap.routes.find((item) => item.path === route);
  const graph = [];

  if (route === "/" || route === "/company/") {
    graph.push({
      "@type": "Organization",
      "@id": organizationId,
      name: content.brand.name,
      legalName: content.brand.legalName,
      url: `${siteUrl}/`,
      logo: {
        "@type": "ImageObject",
        url: `${siteUrl}${content.brand.logoPath}`,
        width: 512,
        height: 512,
      },
      email: content.contact.email,
      contactPoint: {
        "@type": "ContactPoint",
        contactType: "sales",
        email: content.contact.email,
        telephone: content.contact.whatsappLabel,
        availableLanguage: ["es"],
      },
      sameAs: [content.contact.instagramUrl],
    });
  }

  if (route === "/") {
    graph.push({
      "@type": "WebSite",
      "@id": websiteId,
      url: `${siteUrl}/`,
      name: content.brand.name,
      description: content.brand.positioning,
      inLanguage: "es",
      publisher: { "@id": organizationId },
    });

    if (engagementRoutes.length) {
      graph.push({
        "@type": "ItemList",
        "@id": `${siteUrl}/#starting-routes`,
        name: "Formas de empezar con YC Systems",
        itemListElement: engagementRoutes.map((item, index) => ({
          "@type": "ListItem",
          position: index + 1,
          item: {
            "@type": "Service",
            name: item.label,
            description: item.description,
            provider: { "@id": organizationId },
          },
        })),
      });
    }

    if (buyerFaqs.length) {
      graph.push({
        "@type": "FAQPage",
        "@id": `${siteUrl}/#buyer-faq`,
        mainEntity: buyerFaqs.map((item) => ({
          "@type": "Question",
          name: item.question,
          acceptedAnswer: {
            "@type": "Answer",
            text: item.answer,
          },
        })),
      });
    }
  }

  graph.push({
    "@type": route === "/contact/" ? "ContactPage" : "WebPage",
    "@id": pageId,
    url: canonical,
    name: cleanTitle,
    description: cleanDescription,
    inLanguage: "es",
    isPartOf: { "@id": websiteId },
    about: { "@id": organizationId },
    primaryImageOfPage: {
      "@type": "ImageObject",
      url: ogImage,
      width: 1200,
      height: 630,
    },
  });

  if (route !== "/") {
    graph.push({
      "@type": "BreadcrumbList",
      "@id": `${canonical}#breadcrumb`,
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Inicio", item: `${siteUrl}/` },
        { "@type": "ListItem", position: 2, name: routeDefinition?.label || cleanTitle.replace(/\s+\|\s+YC Systems$/, ""), item: canonical },
      ],
    });
  }

  return JSON.stringify({ "@context": "https://schema.org", "@graph": graph }).replace(/</g, "\\u003c");
}

